    /// <summary>Exposes the existing game controls to Windows Narrator through Unity's native accessibility tree.</summary>
    internal sealed class GameAccessibility : MonoBehaviour
    {
        internal enum View { Board, Restart, Victory, Always }

        private sealed class Control
        {
            internal Button Button;
            internal AccessibilityNode Node;
            internal Func<string> Label;
            internal View View;
        }

        private readonly List<Control> controls = new List<Control>();
        private readonly Vector3[] corners = new Vector3[4];
        private AccessibilityHierarchy hierarchy;
        private AssistiveSupport.ScreenReaderStatusOverride previousOverride;
        private View currentView;
        private View publishedView;
        private GameObject lastFocused;
        private bool refreshPending;
        private string announcement;

        internal void Initialize()
        {
            hierarchy = new AccessibilityHierarchy();
            previousOverride = AssistiveSupport.screenReaderStatusOverride;
            // Unity 6.3 may not detect Narrator on Windows. Keep the tree available without starting Narrator.
            AssistiveSupport.screenReaderStatusOverride = AssistiveSupport.ScreenReaderStatusOverride.ForceEnabled;
        }

        internal void Register(Button button, Func<string> label, View view = View.Board)
        {
            var node = hierarchy.AddNode(label());
            node.role = AccessibilityRole.Button;
            node.frameGetter = () => GetScreenFrame((RectTransform)button.transform);
            node.focusChanged += (_, focused) =>
            {
                if (focused && CanInvoke(node, button)) button.Select();
            };
            node.invoked += () =>
            {
                if (!CanInvoke(node, button)) return false;
                button.Select();
                // Submit through the same handlers as Enter, including custom piece and destination controls.
                return ExecuteEvents.Execute(button.gameObject, new BaseEventData(EventSystem.current), ExecuteEvents.submitHandler);
            };
            controls.Add(new Control { Button = button, Node = node, Label = label, View = view });
        }

        internal void Publish()
        {
            Refresh(View.Board);
            UpdateNodes();
            AssistiveSupport.activeHierarchy = hierarchy;
        }

        internal void Refresh(View view)
        {
            currentView = view;
            refreshPending = true;
        }

        internal void Announce(string message) => announcement = message;

        private void LateUpdate()
        {
            if (hierarchy == null || AssistiveSupport.activeHierarchy != hierarchy) return;
            bool screenChanged = publishedView != currentView;
            bool layoutChanged = refreshPending && UpdateNodes();
            var focused = EventSystem.current?.currentSelectedGameObject;
            var node = controls.Find(control => control.Button.gameObject == focused)?.Node;
            if (node != null && !node.isActive) node = null;
            var notifications = AssistiveSupport.notificationDispatcher;
            if (screenChanged)
                notifications.SendScreenChanged(node);
            else if (layoutChanged || (focused != lastFocused && node != null && !node.isFocused))
                notifications.SendLayoutChanged(node);
            lastFocused = focused;
            publishedView = currentView;

            if (announcement == null) return;
            notifications.SendAnnouncement(announcement);
            announcement = null;
        }

        // Keep the controls in the tree across changes so opening a dialog does not reuse stale actions.
        private bool UpdateNodes()
        {
            bool layoutChanged = false;
            foreach (var control in controls)
            {
                var node = control.Node;
                bool visible = (control.View == currentView || control.View == View.Always)
                    && control.Button.gameObject.activeInHierarchy;
                if (node.isActive != visible)
                {
                    node.isActive = visible;
                    layoutChanged = true;
                }
                var state = control.Button.IsInteractable() ? AccessibilityState.None : AccessibilityState.Disabled;
                if (node.state != state) node.state = state;
                string label = control.Label();
                if (node.label != label) node.label = label;
            }
            refreshPending = false;
            return layoutChanged;
        }

        private static bool CanInvoke(AccessibilityNode node, Button button)
        {
            return node.isActive && button.isActiveAndEnabled && button.IsInteractable();
        }

        private Rect GetScreenFrame(RectTransform control)
        {
            control.GetWorldCorners(corners);
            var bottomLeft = RectTransformUtility.WorldToScreenPoint(null, corners[0]);
            var topRight = RectTransformUtility.WorldToScreenPoint(null, corners[2]);
            return Rect.MinMaxRect(bottomLeft.x, Screen.height - topRight.y, topRight.x, Screen.height - bottomLeft.y);
        }

        private void OnDestroy()
        {
            if (hierarchy == null) return;
            if (AssistiveSupport.activeHierarchy == hierarchy) AssistiveSupport.activeHierarchy = null;
            AssistiveSupport.screenReaderStatusOverride = previousOverride;
